using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 Node3D droneRoot;int droneVisualSerial=-1;double droneNoiseClock;
 ExpeditionDroneEvent Drone=>game.World.Changes.Drone;
 void StartDrone(Vector3 at){if(LetterNodeLive(droneRoot)){droneRoot.Visible=false;droneRoot.GetNodeOrNull<AudioStreamPlayer3D>("Alarm")?.Stop();}Drone.Serial++;Drone.State=1;Drone.X=at.X;Drone.Z=at.Z;Drone.Remaining=180;Drone.Waves=0;game.Notice="DISTRESS BEACON / A salvage drone has fallen nearby. Its alarm will attract infected. F to salvage or silence it.";game.Persist();if(CoopHost&&coopActors.Count>0)Rpc(nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));}
 void TickDrone(double dt){if(!EncountersEnabled||CoopClient||dungeon!=null)return;if(Drone.State==1){droneNoiseClock-=dt;if(droneNoiseClock<=0){HearNoise(Ground(Drone.X,Drone.Z),75);droneNoiseClock=2;}Drone.Remaining=Math.Max(0,Drone.Remaining-dt);if(Drone.Remaining<=0){FinishDrone();return;}if(Drone.Waves<3&&Drone.Remaining<=150-Drone.Waves*45&&MillPlayers().Any(p=>Distance(p.Body.Position,Ground(Drone.X,Drone.Z))<110)){int wave=Drone.Waves++;for(int i=0;i<3;i++){double a=(i+wave*3)*2.399;double x=Drone.X+Math.Cos(a)*38,z=Drone.Z+Math.Sin(a)*38;if(!OutdoorFree(x,z)||MillPlayers().Any(p=>Distance(p.Body.Position,Ground(x,z))<22))continue;string id=$"event/drone/{game.Save.Seed}/{Drone.Serial}/{wave}/{i}";AddEnemy(id,x,z,Math.Min(3,game.World.Tier(x,z)));var enemy=infected.Find(e=>e.Id==id);if(enemy!=null){enemy.Memory=12;enemy.Target=Ground(Drone.X,Drone.Z);}}}}
 else if(game.World.Changes.Time>=Drone.Due){var candidate=MillPlayers().FirstOrDefault(p=>game.World.Tier(p.Body.Position.X,p.Body.Position.Z)>=2);if(candidate.Body==null)return;Drone.Due=game.World.Changes.Time+180;uint roll=game.World.Hash((int)(Drone.Due/180),Drone.Serial+187);if(roll%100>=45)return;for(int j=0;j<16;j++){double a=j*.71,x=candidate.Body.Position.X+Math.Cos(a)*35,z=candidate.Body.Position.Z+Math.Sin(a)*35;if(OutdoorFree(x,z)&&!InEncounterLot(x,z)){StartDrone(Ground(x,z));break;}}}}
 void FinishDrone(){Drone.State=2;Drone.Due=game.World.Changes.Time+720+(game.World.Hash(Drone.Serial,933)%360);game.Persist();if(CoopHost&&coopActors.Count>0)Rpc(nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));}
 void SpawnDrone(){if(!EncountersEnabled||dungeon!=null||Drone.State!=1||!NearActiveSurface(Ground(Drone.X,Drone.Z),200))return;string id=$"event/drone/{Drone.Serial}";if(!uniqueObjects.Add(id))return;droneVisualSerial=Drone.Serial;droneRoot=new Node3D{Name="DistressDrone",Position=Ground(Drone.X,Drone.Z)};worldRoot.AddChild(droneRoot);props.Add(new(){Id=id,Kind=28,Node=droneRoot,Position=droneRoot.Position});Bevel(droneRoot,new(0,.4f,0),new(.8f,.5f,.6f),Steel);for(int i=0;i<4;i++){float x=i%2==0?-.8f:.8f,z=i<2?-.6f:.6f;Tube(droneRoot,new(0,.5f,0),new(x,.5f,z),.04f,Steel);Tube(droneRoot,new(x-.35f,.55f,z),new(x+.35f,.55f,z),.025f,Ink);}Box(droneRoot,new(0,.18f,0),new(.9f,.25f,.8f),new(.47f,.36f,.20f),true);droneRoot.AddChild(new OmniLight3D{Name="Beacon",Position=new(0,1,0),LightColor=new(1,.2f,.06f),OmniRange=12,LightEnergy=2});droneRoot.AddChild(new Label3D{Text="DISTRESS / SIGNAL ACTIVE",Position=new(0,1.8f,0),FontSize=26,PixelSize=.007f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled});}
  AudioStreamWav DroneAlarm(){const int rate=22050;var data=new byte[rate*2];for(int i=0;i<rate;i++){double t=i/(double)rate;short value=(short)(t<.14||t>.25&&t<.39?Math.Sin(t*2*Math.PI*720)*8000:0);data[i*2]=(byte)value;data[i*2+1]=(byte)(value>>8);}return new(){Format=AudioStreamWav.FormatEnum.Format16Bits,MixRate=rate,Data=data,LoopMode=AudioStreamWav.LoopModeEnum.Forward,LoopEnd=rate};}
 void DrawDrone(){if(!LetterNodeLive(droneRoot))return;droneRoot.Visible=dungeon==null&&Drone.State==1&&droneVisualSerial==Drone.Serial;if(!testing&&DisplayServer.GetName()!="headless"){var alarm=droneRoot.GetNodeOrNull<AudioStreamPlayer3D>("Alarm");if(alarm==null){alarm=new(){Name="Alarm",Stream=DroneAlarm(),MaxDistance=90,UnitSize=8,VolumeDb=-16};droneRoot.AddChild(alarm);alarm.Play();}alarm.StreamPaused=!droneRoot.Visible||paused||muted;}if(droneRoot.GetNodeOrNull<OmniLight3D>("Beacon") is {} light)light.LightEnergy=droneRoot.Visible?(float)(1+Math.Sin(Time.GetTicksMsec()/140.0)):0;}
 bool NearDrone()=>EncountersEnabled&&dungeon==null&&Drone.State==1&&player.Position.DistanceTo(Ground(Drone.X,Drone.Z))<3;
 bool DroneInteract(){if(!NearDrone())return false;if(!CoopRequest("drone","open"))DroneAction("open");return true;}
 void DroneAction(string op){if(CoopClient||!NearDrone())return;if(op=="open"){if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopDronePage));else ShowDronePage();return;}if(op=="salvage"){if(!game.Change(()=>{game.Craft.Materials[3]+=3;game.Craft.Materials[0]+=4;game.Life.Bandages+=2;game.AwardResearch("drone/"+Drone.Serial,5);}))return;game.Notice="Recovered resin, timber and two bandages. Anyone drawn by the beacon is still nearby.";}else if(op=="silence")game.Notice="Beacon dismantled / supplies lost, further waves cancelled.";else return;FinishDrone();}
 void ShowDronePage(){var b=Panel("DISTRESS DRONE");Text(b,$"A broken delivery drone is broadcasting a rescue signal. No rescue is coming.\n\nThe casing holds useful materials, but the noise carries.\nBEACON BATTERY / {Drone.Remaining:0} seconds");Button(b,"SALVAGE SUPPLIES AND DISCONNECT",()=>DroneChoice("salvage"));Button(b,"DESTROY THE BEACON / LOSE THE SUPPLIES",()=>DroneChoice("silence"));Button(b,"LEAVE",CloseMenu);}
 void DroneChoice(string op){CloseMenu();if(!CoopRequest("drone",op))DroneAction(op);}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopDronePage(){if(CoopClient)ShowDronePage();}
}
